import { writeFile, rename, unlink } from 'fs/promises';
import { randomBytes } from 'crypto';
import { dirname } from 'path';
import { logger } from './logger';

/**
 * Atomically writes data to a file using write-then-rename pattern
 * This prevents file corruption if the process crashes during write
 * @param filePath The target file path
 * @param data The data to write
 * @param encoding The file encoding (default: 'utf-8')
 */
export const atomicWriteFile = async (
   filePath: string,
   data: string,
   encoding: BufferEncoding = 'utf-8'
): Promise<void> => {
   // Generate a temporary file path with random suffix (16 bytes for stronger entropy)
   const tempFilePath = `${filePath}.tmp.${randomBytes(16).toString('hex')}`;

   try {
      // Write to temporary file first
      // eslint-disable-next-line security/detect-non-literal-fs-filename
      await writeFile(tempFilePath, data, { encoding });

      // Atomic rename - this is atomic on most filesystems
      // eslint-disable-next-line security/detect-non-literal-fs-filename
      await rename(tempFilePath, filePath);
   } catch (error) {
      // Clean up temp file if it exists
      try {
         // eslint-disable-next-line security/detect-non-literal-fs-filename
         await unlink(tempFilePath);
      } catch (_cleanupError) {
         // Ignore cleanup errors - file might not exist
      }

      const err = error instanceof Error ? error : new Error(String(error));
      const nodeError = err as NodeJS.ErrnoException;

      // Provide clearer error message if directory doesn't exist
      if (nodeError.code === 'ENOENT') {
         const dir = dirname(filePath);
         logger.error('Atomic write failed: parent directory does not exist', err, {
            targetPath: filePath,
            tempPath: tempFilePath,
            directory: dir,
            suggestion: 'Ensure the parent directory exists before writing',
         });
      } else {
         logger.error('Atomic write failed', err, {
            targetPath: filePath,
            tempPath: tempFilePath,
         });
      }

      throw error;
   }
};

context.utils/branding.ts:
import { normalizeToBoolean } from './dbBooleans';
import { trimString } from './security';

export type BrandingConfig = {
   defaultPlatformName: string;
   whiteLabelEnabled: boolean;
   platformName: string;
   logoFile: string;
   hasCustomLogo: boolean;
   logoMimeType: string;
   logoApiPath: string;
};

export const DEFAULT_PLATFORM_NAME = 'SerpBear';
const DEFAULT_LOGO_FILE = 'branding-logo.png';

const LOGO_MIME_TYPES: Record<string, string> = {
   '.png': 'image/png',
   '.jpg': 'image/jpeg',
   '.jpeg': 'image/jpeg',
   '.gif': 'image/gif',
   '.svg': 'image/svg+xml',
   '.webp': 'image/webp',
};

const stripTrailingSlash = (value: string): string => (value.endsWith('/') ? value.slice(0, -1) : value);

export const DEFAULT_BRANDING: BrandingConfig = {
   defaultPlatformName: DEFAULT_PLATFORM_NAME,
   whiteLabelEnabled: false,
   platformName: DEFAULT_PLATFORM_NAME,
   logoFile: DEFAULT_LOGO_FILE,
   hasCustomLogo: false,
   logoMimeType: '',
   logoApiPath: '/api/branding/logo',
};

export const getLogoMimeType = (fileName: string): string => {
   const lastDot = fileName.lastIndexOf('.');
   if (lastDot === -1) {
      return '';
   }

   const extension = fileName.slice(lastDot).toLowerCase();
   return LOGO_MIME_TYPES[extension] || '';
};

export const getBranding = (): BrandingConfig => {
   const whiteLabelEnabled = normalizeToBoolean(process.env.NEXT_PUBLIC_WHITE_LABEL);
   const platformNameSetting = trimString(process.env.NEXT_PUBLIC_PLATFORM_NAME);
   const logoFileSetting = trimString(process.env.WHITE_LABEL_LOGO_FILE || DEFAULT_LOGO_FILE);
   const logoMimeType = getLogoMimeType(logoFileSetting);
   const hasCustomLogo = whiteLabelEnabled && !!logoMimeType && !!logoFileSetting;

   const platformName = whiteLabelEnabled && platformNameSetting
      ? platformNameSetting
      : DEFAULT_PLATFORM_NAME;

   return {
      defaultPlatformName: DEFAULT_PLATFORM_NAME,
      whiteLabelEnabled,
      platformName,
      logoFile: logoFileSetting,
      hasCustomLogo,
      logoMimeType,
      logoApiPath: '/api/branding/logo',
   } as const;
};

type BuildLogoUrlFirstArg = BrandingConfig | string | undefined;

export const buildLogoUrl = (brandingOrOrigin?: BuildLogoUrlFirstArg, originOverride = ''): string => {
   const branding = typeof brandingOrOrigin === 'string' || brandingOrOrigin === undefined
      ? getBranding()
      : brandingOrOrigin;

   const origin = typeof brandingOrOrigin === 'string' || brandingOrOrigin === undefined
      ? (brandingOrOrigin || '')
      : originOverride;

   if (!branding.hasCustomLogo) {
      return '';
   }

   const sanitizedOrigin = origin ? stripTrailingSlash(origin) : '';
   return `${sanitizedOrigin}${branding.logoApiPath}`;
};

context.utils/dbBooleans.ts:
/**
 * Converts a value to a SQLite boolean integer (1 or 0).
 *
 * Accepts booleans, numbers, null, and undefined, and uses standard JavaScript
 * truthiness: truthy values map to 1, falsy values (0, null, undefined, false) map to 0.
 */
export const toDbBool = (value: boolean | number | null | undefined): 1 | 0 => value ? 1 : 0;

/**
 * Converts a SQLite integer (1 or 0) to boolean
 */
export const fromDbBool = (value: number | null | undefined): boolean => value === 1;

/**
 * Normalizes various value types to boolean.
 * Handles API responses, database values, and user inputs.
 * Uses a conservative approach: only explicitly recognized truthy values return true.
 * 
 * @param value - The value to normalize
 * @returns boolean representation
 * 
 * Recognized truthy values:
 *  - boolean `true`
 *  - non-zero numbers (e.g. `1`)
 *  - strings (case-insensitive, trimmed): `'true'`, `'1'`, `'yes'`, `'on'`
 * All other values (including `false`, `0`, `'false'`, `'0'`, `'no'`, `'off'`,
 * unrecognized strings, `null`, `undefined`, objects, arrays) return `false`.
 * 
 * @example
 * normalizeToBoolean(1) // true (DB integer)
 * normalizeToBoolean('true') // true (API string)
 * normalizeToBoolean('yes') // true
 * normalizeToBoolean('0') // false (string number)
 * normalizeToBoolean('error') // false (unrecognized string)
 * normalizeToBoolean(null) // false (null/undefined)
 */
export const normalizeToBoolean = (value: unknown): boolean => {
   // Handle boolean directly
   if (typeof value === 'boolean') {
      return value;
   }

   // Handle numbers (DB integers: 1 = true, 0 = false)
   if (typeof value === 'number') {
      return value !== 0;
   }

   // Handle strings (API responses, user input)
   if (typeof value === 'string') {
      const normalized = value.trim().toLowerCase();
      // Only explicitly recognized truthy strings return true
      if (normalized === 'true' || normalized === '1' || normalized === 'yes' || normalized === 'on') {
         return true;
      }
      // All other strings (including empty, 'false', '0', 'no', 'off', errors, etc.) return false
      return false;
   }

   // Null, undefined, and any other types return false (conservative approach)
   return false;
};

context.utils/logger.ts:
/**
 * Enhanced logging utility for SerpBear
 * Provides structured logging with different levels and Docker-friendly output
 * 
 * All logs are output to stdout (console.log) in JSON format for Docker container logging.
 * Docker will capture these logs and they can be viewed with: docker logs <container>
 * 
 * Log Levels:
 * - none: Disables all logging
 * - info: Logs high-level operational messages, including key actions and success or failure states (default)
 * - error: Logs detailed error information, including context needed for troubleshooting
 * - debug: Logs full diagnostic output, including API requests, responses, and internal processing details
 * 
 * Example log output:
 * {"timestamp":"2026-01-21T06:00:00.000Z","level":"INFO","message":"GET /api/domains - 200 (150ms)"}
 */

export enum LogLevel {
  NONE = -1,  // No logging
  ERROR = 0,
  WARN = 1,
  INFO = 2,
  DEBUG = 3,
}

export interface LogEntry {
  timestamp: string;
  level: string;
  message: string;
  meta?: Record<string, any>;
  error?: {
    name: string;
    message: string;
    stack?: string;
  };
}

export class Logger {
  private logLevel: LogLevel;

  constructor() {
    // Set log level from environment or default to INFO
    const envLogLevel = process.env.LOG_LEVEL?.toLowerCase();

    // Support for disabling logging: none, false, 0, off
    if (envLogLevel === 'none' || envLogLevel === 'false' || envLogLevel === '0' || envLogLevel === 'off') {
      this.logLevel = LogLevel.NONE;
    } else if (!envLogLevel || envLogLevel === 'info') {
      // Default to INFO level when undefined or explicitly set to 'info'
      this.logLevel = LogLevel.INFO;
    } else {
      switch (envLogLevel) {
        case 'error':
          this.logLevel = LogLevel.ERROR;
          break;
        case 'warn':
          this.logLevel = LogLevel.WARN;
          break;
        case 'debug':
          this.logLevel = LogLevel.DEBUG;
          break;
        default:
          // If invalid value, default to INFO
          this.logLevel = LogLevel.INFO;
      }
    }
  }

  private static formatLogEntry(level: string, message: string, meta?: Record<string, any>, error?: Error): string {
    const logEntry: LogEntry = {
      timestamp: new Date().toISOString(),
      level,
      message,
    };

    if (meta) {
      logEntry.meta = meta;
    }

    if (error) {
      logEntry.error = {
        name: error.name,
        message: error.message,
        stack: error.stack,
      };
    }

    return JSON.stringify(logEntry);
  }

  private log(level: LogLevel, levelName: string, message: string, meta?: Record<string, any>, error?: Error): void {
    if (level <= this.logLevel) {
      const formattedLog = Logger.formatLogEntry(levelName, message, meta, error);
      // eslint-disable-next-line no-console
      console.log(formattedLog);
    }
  }

  error(message: string, error?: Error, meta?: Record<string, any>): void {
    this.log(LogLevel.ERROR, 'ERROR', message, meta, error);
  }

  warn(message: string, meta?: Record<string, any>): void {
    this.log(LogLevel.WARN, 'WARN', message, meta);
  }

  info(message: string, meta?: Record<string, any>): void {
    this.log(LogLevel.INFO, 'INFO', message, meta);
  }

  debug(message: string, meta?: Record<string, any>): void {
    this.log(LogLevel.DEBUG, 'DEBUG', message, meta);
  }

  // Authentication event logging
  authEvent(event: string, user?: string, success: boolean = true, meta?: Record<string, any>): void {
    if (success) {
      // INFO level: Log auth success with structured metadata
      this.info(`Auth: ${event}${user ? ` [${user}]` : ''}`, {
        event,
        user,
        ...meta,
      });
    } else {
      // WARN level: Log auth failures with some context
      this.warn(`Auth Failed: ${event}`, {
        event,
        user,
        ...meta,
      });
    }
  }
}

export const logger = new Logger();
export default logger;

context.utils/parseKeywords.ts:
import Keyword from '../database/models/keyword';
import { normalizeToBoolean } from './dbBooleans';
import { safeJsonParse } from './safeJsonParse';

export const normaliseHistory = (rawHistory: unknown): KeywordHistory => {
   if (!rawHistory || typeof rawHistory !== 'object' || Array.isArray(rawHistory)) {
      return {};
   }

   return Object.entries(rawHistory as Record<string, unknown>).reduce<KeywordHistory>((acc, [key, value]) => {
      if (!key) { return acc; }

      const numericValue = typeof value === 'number' ? value : Number(value);
      if (!Number.isNaN(numericValue)) {
         acc[key] = numericValue;
      }
      return acc;
   }, {});
};

/**
 * Parses the SQL Keyword Model object to frontend cosumable object.
 * @param {Keyword[]} allKeywords - Keywords to scrape
 * @returns {KeywordType[]}
 */
const parseKeywords = (allKeywords: Keyword[]) : KeywordType[] => {
   const parsedItems = allKeywords.map((keywrd:Keyword) => {
      const keywordData = keywrd as unknown as Record<string, any>;

      const historyRaw = typeof keywordData.history === 'string' 
         ? safeJsonParse<unknown>(keywordData.history, {}, {})
         : (keywordData.history || {});
      const history = normaliseHistory(historyRaw);

      const rawHistory7d = keywordData.history7d;
      const history7d = rawHistory7d != null
         ? normaliseHistory(
            typeof rawHistory7d === 'string'
               ? safeJsonParse<unknown>(rawHistory7d, {}, {})
               : (rawHistory7d || {}),
         )
         : undefined;

      const tags = typeof keywordData.tags === 'string'
         ? safeJsonParse<string[]>(keywordData.tags, [], {})
         : (Array.isArray(keywordData.tags) ? keywordData.tags : []);

      const lastResult = typeof keywordData.lastResult === 'string'
         ? safeJsonParse<any[]>(keywordData.lastResult, [], {})
         : (Array.isArray(keywordData.lastResult) ? keywordData.lastResult : []);

      const localResults = typeof keywordData.localResults === 'string'
         ? safeJsonParse<any[]>(keywordData.localResults, [], {})
         : (Array.isArray(keywordData.localResults) ? keywordData.localResults : []);

      let lastUpdateError: any = false;
      if (typeof keywordData.lastUpdateError === 'string' && keywordData.lastUpdateError !== 'false' && keywordData.lastUpdateError.includes('{')) {
         lastUpdateError = safeJsonParse<any>(keywordData.lastUpdateError, {}, {});
      }

      return {
         ...keywordData,
         location: typeof keywordData.location === 'string' ? keywordData.location : '',
         history,
         ...(history7d !== undefined ? { history7d } : {}),
         tags,
         lastResult,
         localResults,
         lastUpdateError,
         sticky: normalizeToBoolean(keywordData.sticky),
         updating: normalizeToBoolean(keywordData.updating),
         mapPackTop3: normalizeToBoolean(keywordData.mapPackTop3),
      } as KeywordType;
   });
   return parsedItems;
};

export default parseKeywords;

context.utils/refreshQueue.ts:
/**
 * Refresh Queue Manager with Parallel Domain Processing
 * 
 * Allows multiple domains to be processed in parallel while preventing:
 * 1. The same domain from being refreshed multiple times simultaneously
 * 2. Database conflicts by ensuring each domain only touches its own rows
 * 
 * Features:
 * - Configurable concurrency limit for parallel processing
 * - Per-domain locking to prevent duplicate refreshes
 * - Automatic retry of queued tasks when a slot becomes available
 */

import { logger } from './logger';

type RefreshTask = {
   id: string;
   domains: Set<string>;
   execute: () => Promise<void>;
};

class RefreshQueue {
   private queue: RefreshTask[] = [];
   private activeProcesses = new Map<string, Promise<void>>(); // Track active processes by task ID
   private activeDomains = new Set<string>(); // Track which domains are currently being processed
   private maxConcurrency: number;

   constructor() {
      // Read concurrency from environment variable, default to 3
      const envConcurrency = process.env.REFRESH_QUEUE_CONCURRENCY;
      const parsedConcurrency = envConcurrency ? parseInt(envConcurrency, 10) : 3;

      // Validate and set concurrency (must be at least 1)
      this.maxConcurrency = Number.isFinite(parsedConcurrency) && parsedConcurrency >= 1 
         ? parsedConcurrency 
         : 3;

      if (envConcurrency && parsedConcurrency !== this.maxConcurrency) {
         logger.warn(`Invalid REFRESH_QUEUE_CONCURRENCY value "${envConcurrency}", using default: ${this.maxConcurrency}`);
      } else if (envConcurrency && this.maxConcurrency !== 3) {
         logger.info(`Refresh queue concurrency set to ${this.maxConcurrency} via environment variable`);
      }
   }

   /**
    * Add a refresh task to the queue
    * @param taskId Unique identifier for this task
    * @param domains Complete set of domain names touched by the task
    * @param task The async function to execute
    */
   async enqueue(taskId: string, task: () => Promise<void>, domains: Iterable<string> = []): Promise<void> {
      const normalizedDomains = new Set(Array.from(domains, (domain) => domain.trim().toLowerCase()).filter(Boolean));
      logger.info(`Enqueueing refresh task: ${taskId}`, { domains: Array.from(normalizedDomains) });

      // Check whether any task domain is already being processed
      if (Array.from(normalizedDomains).some((domain) => this.activeDomains.has(domain))) {
         logger.info('One or more task domains are already being processed, queueing task', { taskId, domains: Array.from(normalizedDomains) });
      }

      this.queue.push({
         id: taskId,
         domains: normalizedDomains,
         execute: task,
      });

      logger.debug(`Queue status`, { 
         queueLength: this.queue.length, 
         activeProcesses: this.activeProcesses.size,
         activeDomains: Array.from(this.activeDomains),
      });

      // Try to start processing tasks if we have capacity
      this.processQueue();
   }

   /**
    * Process queued tasks with parallel execution up to maxConcurrency limit
    */
   private processQueue(): void {
      // Continue while we have capacity and queued tasks
      while (this.activeProcesses.size < this.maxConcurrency && this.queue.length > 0) {
         // Find the next task that can be processed (not blocked by domain lock)
         const taskIndex = this.queue.findIndex(task => 
            Array.from(task.domains).every((domain) => !this.activeDomains.has(domain))
         );

         if (taskIndex === -1) {
            // All remaining tasks are blocked by active domain locks
            logger.debug('No available tasks (all blocked by domain locks)', {
               queueLength: this.queue.length,
               activeDomains: Array.from(this.activeDomains),
            });
            break;
         }

         // Remove task from queue and start processing
         const task = this.queue.splice(taskIndex, 1)[0];
         this.startTask(task);
      }
   }

   /**
    * Start processing a single task
    */
   private startTask(task: RefreshTask): void {
      const domains = Array.from(task.domains);
      logger.info(`Starting refresh task: ${task.id}`, { domains });
      const startTime = Date.now();

      // Mark domain as active if specified
      // processQueue is synchronous, so marking the complete set here is atomic
      // with respect to selection of the next task.
      domains.forEach((domain) => this.activeDomains.add(domain));

      // Create and track the promise
      const taskPromise = task.execute()
         .then(() => {
            const duration = Date.now() - startTime;
            logger.info(`Completed refresh task: ${task.id} (${duration}ms)`, { domains });
         })
         .catch((error) => {
            const duration = Date.now() - startTime;
            logger.error(`Failed refresh task: ${task.id} (${duration}ms)`, error instanceof Error ? error : new Error(String(error)), { domains });
         })
         .finally(() => {
            // Clean up: remove from active tracking
            this.activeProcesses.delete(task.id);
            domains.forEach((domain) => this.activeDomains.delete(domain));

            // Try to process more tasks now that we have a free slot
            this.processQueue();
         });

      this.activeProcesses.set(task.id, taskPromise);
   }

   /**
    * Check if a domain is currently being processed or queued
    */
   isDomainLocked(domain: string): boolean {
      const normalizedDomain = domain.trim().toLowerCase();
      // A domain is considered locked if it is either actively being processed
      // or has a pending task in the queue.
      return this.activeDomains.has(normalizedDomain) || this.queue.some(task => task.domains.has(normalizedDomain));
   }

   /**
    * Get current queue status
    */
   getStatus() {
      return {
         queueLength: this.queue.length,
         activeProcesses: this.activeProcesses.size,
         activeDomains: Array.from(this.activeDomains),
         pendingTaskIds: this.queue.map(t => t.id),
         maxConcurrency: this.maxConcurrency,
      };
   }

   /**
    * Set the maximum number of concurrent tasks
    */
   setMaxConcurrency(max: number): void {
      if (max < 1) {
         throw new Error('Max concurrency must be at least 1');
      }
      this.maxConcurrency = max;
      logger.info(`Updated max concurrency to ${max}`);

      // Try to process more tasks if we increased the limit
      this.processQueue();
   }
}

// Singleton instance
export const refreshQueue = new RefreshQueue();

context.utils/retryQueueManager.ts:
import { readFile, mkdir } from 'fs/promises';
import { dirname } from 'path';
import { atomicWriteFile } from './atomicWrite';
import * as lockfile from 'proper-lockfile';
import { logger } from './logger';

/**
 * Retry Queue Manager with concurrency-safe file operations
 * 
 * This manager ensures that the failed_queue.json file is accessed safely
 * when multiple parallel domain processes are running. It uses a file-based
 * lock to serialize read-modify-write operations across processes.
 */

class RetryQueueManager {
   private filePath: string;

   constructor() {
      this.filePath = `${process.cwd()}/data/failed_queue.json`;
   }

   /**
    * Serializes operations to ensure only one read-modify-write cycle happens at a time,
    * using an OS-level file lock so that multiple Node.js processes cannot interleave
    * their read-modify-write sequences.
    */
   private async withLock<T>(operation: () => Promise<T>): Promise<T> {
      let release: () => Promise<void>;

      // Ensure the queue file exists before trying to lock it
      try {
         // eslint-disable-next-line security/detect-non-literal-fs-filename
         await readFile(this.filePath, { encoding: 'utf-8' });
      } catch (err: any) {
         if (err.code === 'ENOENT') {
            // File doesn't exist - create it with empty array
            try {
               const dir = dirname(this.filePath);
               // eslint-disable-next-line security/detect-non-literal-fs-filename
               await mkdir(dir, { recursive: true });
               await atomicWriteFile(this.filePath, JSON.stringify([]), 'utf-8');
            } catch (createErr: any) {
               logger.debug('Failed to create retry queue file', { error: createErr?.message });
               throw createErr;
            }
         } else {
            logger.debug('Failed to read retry queue file', { error: err?.message });
            throw err;
         }
      }

      try {
         // Acquire a cross-process file lock on the queue file with retry/backoff.
         release = await lockfile.lock(this.filePath, {
            retries: {
               retries: 5,
               factor: 2,
               minTimeout: 50,
               maxTimeout: 1000,
            },
         });
      } catch (err: any) {
         logger.debug('Failed to acquire retry queue file lock', { error: err?.message });
         throw err;
      }

      try {
         // Execute this operation while holding the file lock.
         return await operation();
      } finally {
         try {
            await release();
         } catch (err: any) {
            // Log but do not rethrow to avoid masking the original operation error.
            logger.debug('Failed to release retry queue file lock', { error: err?.message });
         }
      }
   }

   /**
    * Read the current retry queue from file
    */
   private async readQueue(): Promise<number[]> {
      try {
         // eslint-disable-next-line security/detect-non-literal-fs-filename
         const rawData = await readFile(this.filePath, { encoding: 'utf-8' });
         const parsed = JSON.parse(rawData);
         return Array.isArray(parsed) ? parsed.filter(id => Number.isInteger(id) && id > 0) : [];
      } catch (err: any) {
         if (err.code === 'ENOENT') {
            // File doesn't exist yet - return empty array
            return [];
         }
         logger.debug('Failed to read retry queue', { error: err.message });
         return [];
      }
   }

   /**
    * Write the retry queue to file atomically
    */
   private async writeQueue(queue: number[]): Promise<void> {
      try {
         await atomicWriteFile(this.filePath, JSON.stringify(queue), 'utf-8');
      } catch (err: any) {
         logger.error('Failed to write retry queue', err);
         throw err;
      }
   }

   /**
    * Add a keyword ID to the retry queue (concurrency-safe)
    */
   async addToQueue(keywordID: number): Promise<void> {
      if (!keywordID || !Number.isInteger(keywordID) || keywordID <= 0) {
         return;
      }

      await this.withLock(async () => {
         const queue = await this.readQueue();

         if (!queue.includes(keywordID)) {
            queue.push(keywordID);
            await this.writeQueue(queue);
         }
      });
   }

   /**
    * Remove a keyword ID from the retry queue (concurrency-safe)
    */
   async removeFromQueue(keywordID: number): Promise<void> {
      if (!keywordID || !Number.isInteger(keywordID)) {
         return;
      }

      await this.withLock(async () => {
         const queue = await this.readQueue();
         const filtered = queue.filter(id => id !== Math.abs(keywordID));

         if (filtered.length !== queue.length) {
            await this.writeQueue(filtered);
         }
      });
   }

   /**
    * Remove multiple keyword IDs from the retry queue in a single operation (concurrency-safe)
    */
   async removeBatch(keywordIDs: Set<number>): Promise<void> {
      if (keywordIDs.size === 0) {
         return;
      }

      await this.withLock(async () => {
         const queue = await this.readQueue();
         const filtered = queue.filter(id => !keywordIDs.has(id));

         if (filtered.length !== queue.length) {
            await this.writeQueue(filtered);
         }
      });
   }

   /**
    * Get the current retry queue (for reading only)
    */
   async getQueue(): Promise<number[]> {
      return this.withLock(async () => this.readQueue());
   }

   /**
    * Clear the entire retry queue (concurrency-safe)
    */
   async clearQueue(): Promise<void> {
      await this.withLock(async () => {
         await this.writeQueue([]);
      });
   }
}

// Export singleton instance
export const retryQueueManager = new RetryQueueManager();

